e used in a given experiment step?

SELECT ?usedStep WHERE {
  ?experimentStep a aml:ExperimentStep ;
                  aml:usesMethod ?method .
  ?usedStep a aml:ExperimentStep ;
            aml:producesResult ?result .
  ?method aml:hasSpecification ?specification .
  ?result aml:includes ?referenceSet .
  ?referenceSet aml:pointsTo ?usedStep .
  FILTER(?usedStep != ?experimentStep)
}

