which infrastructures include references to experiments

SELECT ?infrastructure ?experiment
WHERE {
  ?infrastructure a aml:Infrastructure ;
                  aml:includes ?referenceSet .
  ?referenceSet a aml:AnimlReferenceSet ;
                aml:subject ?experiment .
  ?experiment a aml:Experiment .
}

SELECT ?infrastructure WHERE {
  ?infrastructure a aml:Infrastructure ;
                  aml:includes ?refSet .
  ?refSet a aml:AnimlReferenceSet ;
          <http://www.ontologydesignpatterns.org/cp/owl/collectionentity.owl#hasMember> ?ref .
  ?ref a aml:AnimlReference ;
       aml:pointsTo ?sample .
  ?sample a aml:Sample .
  ?ref aml:hasSpecification ?refSpec .
  ?refSpec aml:consumedBy ?technique .
  ?expStep a aml:ExperimentStep ;
           aml:usesTechnique ?technique .
}

PREFIX aml: <http://www.w3id.org/animl/ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?infrastructure
WHERE {
  ?infrastructure a aml:Infrastructure ;
                  aml:includes ?refSet .
  ?refSet a aml:AnimlReferenceSet ;
          aml:subject ?experiment .
  ?experiment a aml:Experiment ;
              <http://www.ontologydesignpatterns.org/cp/owl/collectionentity.owl#hasMember> ?step .
  ?refSet <http://www.ontologydesignpatterns.org/cp/owl/collectionentity.owl#hasMember> ?ref .
  ?ref a aml:AnimlReference ;
       aml:pointsTo ?sample ;
       aml:hasSpecification ?refSpec .
  ?refSpec a aml:AnimlReferenceSpecification ;
           aml:derivedFrom ?technique .
  ?step a aml:ExperimentStep ;
        aml:usesTechnique ?technique ;
        aml:producesResult ?result .
  ?result a aml:Result ;
          aml:includes ?resultRefSet .
  ?resultRefSet <http://www.ontologydesignpatterns.org/cp/owl/collectionentity.owl#hasMember> ?resultRef .
  ?resultRef a aml:AnimlReference ;
             aml:pointsTo ?sample .
}

