SELECT ?seriesSpec
WHERE {
  ?seriesSpec a aml:SeriesSpecification .
  {
    SELECT ?seriesSpec (COUNT(?dpSpec) AS ?dpCount)
    WHERE {
      ?seriesSpec aml:hasPart ?dpSpec .
      ?dpSpec a aml:DataPointSpecification .
    }
    GROUP BY ?seriesSpec
    HAVING (?dpCount > 2 || ?dpCount = 2)
  }
}

