  ?specification a aml:Specification .
}

Which animl references are specified by a given AnimlReferenceSpecification?

SELECT ?animlReference WHERE {
  ?animlReference a aml:AnimlReference ;
                  aml:hasSpecification ?specification .
  ?specification a aml:AnimlReferenceSpecification .
  FILTER(?specification = <SPECIFICATION_URI>)
}

