CQ number 82 for the animl ontology is: Which results are subcategories of a given category?

SELECT ?result WHERE {
  ?result a aml:Result ;
          aml:hasResultCategory ?category .
  ?category aml:hasSubCategory ?subCategory .
  FILTER(?subCategory = :GivenCategory)
}
